    let leaf;
    if (leaves.length > 0) {
      leaf = leaves[0];
      this.app.workspace.revealLeaf(leaf);
    } else {
      leaf = this.app.workspace.getLeaf("split");
      await leaf.setViewState({ type: VIEW_TYPE, active: true });
    }
    if (leaf.view instanceof NotabilityView)
      await leaf.view.loadPDF(file);
